def generate(seed):
    r = random.Random(seed)
    while True:
        W = r.randint(26, 34)
        D = r.randint(4, 6)
        cols = []
        c = 3
        while c <= W - 4:
            if r.random() < 0.4:
                cols.append(c); c += r.randint(5, 7)
            else:
                c += 1
        if not 4 <= len(cols) <= 6:
            continue
        hs = [r.choice((1, 2, 2, 3, 3)) for _ in cols]
        tot = sum(hs)
        if tot < 10 or sum(h > 1 for h in hs) < 3 or max(hs) > D - 1:
            continue
        pool = [k for k in (3, 4, 5) if k <= tot - 4]
        if not pool:
            continue
        N = r.choice(pool)
        p = [0] * W
        for c, h in zip(cols, hs):
            p[c] = h
        out = ["~" * W]
        for i in range(D):
            out.append("".join("|" if q and q >= D - i else "." for q in p))
        out.append("#" * W)
        out.append(str(N))
        return "\n".join(out)

