def parse(clue):
    L = clue.split()
    return L[0], L[1:-2], L[-2], int(L[-1])

def ends(b, W, a, d):
    no = a + 3 if d == 0 else a - 1
    ta = a - 1 if d == 0 else a + 3
    n = 0 <= no < W and b[no] == "|"
    t = 0 <= ta < W and b[ta] == "|"
    return no, ta, n, t

def slots(bg, W):
    nib = []; tal = []; fre = []
    for i in range(len(bg)):
        b = bg[i]
        for a in range(W - 2):
            if b[a:a+3] != "...":
                continue
            for d in (0, 1):
                no, ta, n, t = ends(b, W, a, d)
                if n and t:
                    continue
                if n:
                    nib.append((i, a, d, no))
                elif t:
                    tal.append((i, a, d, ta))
                else:
                    fre.append((i, a, d, -1))
    return nib, tal, fre

def fits(pl, i, a):
    return all(j != i or abs(a - b) >= 4 for (j, b, _, _) in pl)

def draw(surf, bg, grav, pl):
    out = [surf]
    for i in range(len(bg)):
        row = list(bg[i])
        for (j, a, d, _) in pl:
            if j == i:
                row[a:a+3] = list("><>" if d == 0 else "<><")
        out.append("".join(row))
    out.append(grav)
    return "\n".join(out)

def okay(bg, pl, N):
    W = len(bg[0]); D = len(bg)
    F = len(pl); R = nb = tl = g1 = 0
    per = [0] * D; nc = set(); tc2 = set(); rws = set()
    for (i, a, d, _) in pl:
        b = bg[i]
        no, ta, n, t = ends(b, W, a, d)
        f2 = no + 1 if d == 0 else no - 1
        R += d == 0; per[i] += 1; rws.add(i)
        if n:
            nb += 1; nc.add(no)
        elif 0 <= f2 < W and b[f2] == "|":
            g1 += 1
        if t:
            tl += 1; tc2.add(ta)
    tc = nb + tl
    mn = 1 if F < 6 else 2
    bad = {F, R, F - R, tl, tc, F - tc, g1, len(nc | tc2), len(rws),
           per[-1], per[0], max(per)}
    return (nb == N and R >= mn and F - R >= mn and tl >= 1
            and F - tc >= 1 and bool(nc & tc2) and N not in bad)

def both(r, pl, nib, N):
    ds = {q[2] for q in pl[:N]}
    return N < 2 or len(ds) == 2

def pick(r, src, pl, want):
    got = 0
    for k in r.sample(range(len(src)), len(src)):
        if got == want:
            break
        q = src[k]
        if fits(pl, q[0], q[1]):
            pl.append(q); got += 1
    return got == want

def solve(clue):
    surf, bg, grav, N = parse(clue)
    W = len(surf)
    nib, tal, fre = slots(bg, W)
    if len(nib) < N or not tal or not fre:
        return ""
    r = random.Random(clue)
    for _ in range(300):
        pl = []; used = set()
        for k in r.sample(range(len(nib)), len(nib)):
            if len(pl) == N:
                break
            q = nib[k]
            if (q[0], q[3]) in used or not fits(pl, q[0], q[1]):
                continue
            used.add((q[0], q[3])); pl.append(q)
        if len(pl) != N:
            continue
        if not both(r, pl, nib, N):
            continue
        nc = {q[3] for q in pl}
        par = [q for q in tal if q[3] in nc]
        if not pick(r, par or tal, pl, 1) or not pick(r, fre, pl, 1):
            continue
        if r.random() < 0.3:
            pick(r, tal if r.random() < 0.6 else fre, pl, 1)
        if okay(bg, pl, N):
            return draw(surf, bg, grav, pl)
    return ""

